SELECT COUNT(*) AS salesCount, SUM(amount) AS salesAmount FROM transaction_records WHERE type = 3
AND transaction_time >= #{params.startTime}
AND transaction_time <= #{params.endTime}

SELECT DATE_FORMAT(transaction_time, '%Y-%m-%d') AS date, COUNT(*) AS salesCount, SUM(amount) AS salesAmount FROM transaction_records WHERE type = 3
AND transaction_time >= #{params.startTime}
AND transaction_time <= #{params.endTime}
GROUP BY DATE_FORMAT(transaction_time, '%Y-%m-%d') ORDER BY date

SELECT COUNT(*) AS totalTransactions, SUM(amount) AS totalAmount, SUM(CASE WHEN type = 1 THEN 1 ELSE 0 END) AS rechargeCount, SUM(CASE WHEN type = 2 THEN 1 ELSE 0 END) AS withdrawCount, SUM(CASE WHEN type = 3 THEN 1 ELSE 0 END) AS paymentCount FROM transaction_records
AND transaction_time >= #{params.startTime}
AND transaction_time <= #{params.endTime}
